def form_html():
    return '''<form class="form-shell" data-demo-form novalidate><div class="form-grid"><div class="form-field"><label for="first-name">First name</label><input id="first-name" name="firstName" autocomplete="given-name" required></div><div class="form-field"><label for="last-name">Last name</label><input id="last-name" name="lastName" autocomplete="family-name" required></div><div class="form-field"><label for="phone">Phone</label><input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" required></div><div class="form-field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required></div><div class="form-field"><label for="zip">ZIP code</label><input id="zip" name="zip" inputmode="numeric" autocomplete="postal-code" pattern="[0-9]{5}(-[0-9]{4})?" required></div><div class="form-field"><label for="service">Service needed</label><select id="service" name="service" required><option value="">Choose a service</option><option>AC Repair</option><option>Heating Repair</option><option>HVAC Installation / Replacement</option><option>Maintenance</option><option>Indoor Air Quality</option><option>Commercial HVAC</option><option>Other</option></select></div><fieldset class="form-field full" style="border:0;padding:0;margin:0"><legend class="legend">Preferred contact method</legend><div class="radio-row"><label class="radio-option"><input type="radio" name="contactMethod" value="Phone" required><span>Phone</span></label><label class="radio-option"><input type="radio" name="contactMethod" value="Text"><span>Text</span></label><label class="radio-option"><input type="radio" name="contactMethod" value="Email"><span>Email</span></label></div></fieldset><div class="form-field full"><label for="message">Describe the problem</label><textarea id="message" name="message" placeholder="What is your system doing? When did the issue start?"></textarea></div><div class="form-field full"><label class="consent"><input type="checkbox" name="consent" required><span>I agree to be contacted regarding my service request.</span></label></div><div class="form-field full"><button class="button button-accent" type="submit" data-cta="contact-form-submit">Request Service</button><div class="form-status" role="status" tabindex="-1">Demo request received. Connect this form to the client’s CRM, email service, or scheduling platform before launch. No information was transmitted.</div></div></div></form>'''

contact_body=page_hero('Call or request online','Request HVAC Service','Tell us what your system is doing, how to reach you, and which service you need. This static demo does not transmit information.','Contact','Call (214) 555-0147','tel:+12145550147')+f'''<section class="section section-soft" id="request-service"><div class="container contact-layout"><div><p class="eyebrow">Contact details</p><h2>Start With the Easiest Option</h2><p>For immediate scheduling questions, call. For non-urgent requests, use the short form.</p><div class="contact-cards"><div class="contact-card"><strong>Phone</strong><a href="tel:+12145550147">(214) 555-0147</a></div><div class="contact-card"><strong>Email</strong><a href="mailto:service@summitcomfort.example">service@summitcomfort.example</a></div><div class="contact-card"><strong>Demo hours</strong><span>Monday–Saturday, 7 AM–8 PM</span></div><div class="contact-card"><strong>Service area</strong><span>Dallas–Fort Worth and sample surrounding cities</span></div><div class="contact-card"><strong>Customer-facing address</strong><span>Not listed in this demo. Add only a verified public location.</span></div></div></div><div><p class="eyebrow">Short service form</p><h2>How Can We Help?</h2>{form_html()}</div></div></section><section class="section" id="accessibility"><div class="container narrow"><p class="eyebrow">Accessibility</p><h2>Designed for More Customers</h2><p>This demo uses semantic structure, visible keyboard focus, labeled fields, keyboard-operable menus and accordions, large touch targets, readable contrast, and reduced-motion support. A production client site should also receive content, assistive-technology, and user testing.</p><div id="demo-policies"><h2>Policy Placeholders</h2><p>Privacy and terms content must be written for the client’s actual forms, analytics, call tracking, financing providers, messaging practices, and jurisdiction before launch.</p></div></div></section>'''
